using AiReap.Application.Common;
using AiReap.Application.Persistence;
using Microsoft.EntityFrameworkCore;

namespace AiReap.Application.Artifacts;

// S1 - an update to an artifact row only succeeds if the row is unchanged since it was read. Two
// concurrency tokens say so: Artifact.CurrentVersion, the application's version number (moves only
// when the content does), and Artifact.RowVersion, a SQL Server rowversion generated by the database
// (moves on every UPDATE, including status-only promotions and IAiReapDbContext.MarkArtifactForConcurrencyCheck
// touches). Everything one SaveChangesAsync writes (the artifact, its new ArtifactVersion, review or
// work records) is one transaction, so a lost race writes none of it; the context is restored
// (ArtifactPersistence.Undo) and the caller gets a 409 to reload and retry - never an automatic retry.
// Only a concurrency conflict is translated; any other failure propagates unchanged.
public static class ArtifactConcurrency
{
    public const string ChangedMessage = "This artifact changed since you loaded it. Reload and try again.";

    public static async Task SaveAsync(IAiReapDbContext db, CancellationToken cancellationToken)
    {
        try
        {
            await db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            ArtifactPersistence.Undo(db);
            throw new ConflictException(ChangedMessage);
        }
    }
}
